import json

def validate_input(data):
    try:
        content = data.get('content')
        username = data.get('username')
        if not content or not username:
            raise ValueError("Invalid input: content and username are required")
        if len(username) > 100:
            raise ValueError("Invalid input: username exceeds maximum length")
        return True
    except (ValueError, TypeError) as e:
        print(f"Input validation error: {e}")
        return False

# Example usage
data = json.loads('{"content": "hello world!", "username": "alice"}')
